<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';require_login();$code=trim($_GET['code']??'');$s=$pdo->prepare('SELECT * FROM orders WHERE order_code=? AND user_id=?');$s->execute([$code,$_SESSION['user']['id']]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Order not found.');}$pageTitle='Order Confirmed';include __DIR__.'/../includes/partials/header.php';?><div class="confirmation"><h1>Order confirmed 🎉</h1><p>Your order <strong><?=e($order['order_code'])?></strong> has been placed.</p><h2>Total: Rs <?=number_format($order['total'],2)?></h2><a class="btn-primary" href="tracking.php?code=<?=urlencode($order['order_code'])?>">Track Order</a> <a href="orders.php">View Orders</a></div><?php include __DIR__.'/../includes/partials/footer.php';?>